import java.lang.annotation.*;
import java.lang.reflect.*;
import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    @Retention(RetentionPolicy.RUNTIME) @Target(ElementType.METHOD)
    @interface Tx {}

    interface Svc {
        void audited();
        void outerSelfCall();
        void outerExposedCall();
    }

    static final AtomicInteger INTERCEPTED = new AtomicInteger();

    static class SvcImpl implements Svc {
        private Svc exposed;
        void setExposed(Svc s) { this.exposed = s; }
        @Tx public void audited() { }
        public void outerSelfCall() { this.audited(); }
        public void outerExposedCall() { if (exposed != null) exposed.audited(); }
    }

    static class Handler implements InvocationHandler {
        private final Object target;
        Handler(Object t) { this.target = t; }
        private Method impl(Method m) throws NoSuchMethodException {
            return target.getClass().getMethod(m.getName(), m.getParameterTypes());
        }
        public Object invoke(Object proxy, Method m, Object[] args) throws Throwable {
            if (impl(m).isAnnotationPresent(Tx.class)) INTERCEPTED.incrementAndGet();
            return m.invoke(target, args);
        }
    }

    public static void main(String[] args) throws Exception {
        SvcImpl impl = new SvcImpl();
        Svc proxy = (Svc) Proxy.newProxyInstance(
                Svc.class.getClassLoader(), new Class<?>[]{Svc.class}, new Handler(impl));
        impl.setExposed(proxy);

        INTERCEPTED.set(0); proxy.audited();
        boolean viaProxy = INTERCEPTED.get() == 1;

        INTERCEPTED.set(0); proxy.outerSelfCall();
        boolean viaSelfCall = INTERCEPTED.get() == 1;

        INTERCEPTED.set(0); proxy.outerExposedCall();
        boolean viaExposed = INTERCEPTED.get() == 1;

        System.out.println("via proxy direct call  @Tx intercepted: " + viaProxy);
        System.out.println("via this self-call     @Tx intercepted: " + viaSelfCall);
        System.out.println("via exposed proxy call @Tx intercepted: " + viaExposed);
    }
}
